WITH with_dims AS (SELECT e.*, b.status, b.opened_date FROM transactions e LEFT JOIN accounts b ON e.account_id = b.id WHERE b.balance > 36000) SELECT CASE WHEN amount >= 4300 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, SORT_ARRAY(COLLECT_SET(status)) AS status_list, COUNT_IF(merchant = 'Lazada') AS lazada_events, MAX(amount) FILTER (WHERE status = 'OPEN') AS open_max_amount, ROUND(AVG(amount), 2) AS avg_amount, COUNT(*) FILTER (WHERE status = 'CLOSED') AS closed_rows, (UNIX_TIMESTAMP(MAX(txn_time)) - UNIX_TIMESTAMP(MIN(txn_time))) / 60 AS duration_min FROM with_dims GROUP BY CASE WHEN amount >= 4300 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY amount_tier ASC NULLS LAST;
